Index: packages/KNIRVSHELL/cmd/dve_pod.go
===================================================================
--- packages/KNIRVSHELL/cmd/dve_pod.go	
+++ packages/KNIRVSHELL/cmd/dve_pod.go	
@@ -0,0 +1,129 @@
+package cmd
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+
+	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/internal/dvepod"
+	"github.com/spf13/cobra"
+)
+
+func init() {
+	dveCmd.AddCommand(dvePodCmd)
+	dvePodCmd.AddCommand(dvePodNewCmd)
+	dvePodCmd.AddCommand(dvePodRunCmd)
+	dvePodCmd.AddCommand(dvePodListCmd)
+	dvePodCmd.AddCommand(dvePodDockCmd)
+	dvePodCmd.AddCommand(dvePodBundleCmd)
+	dvePodCmd.AddCommand(dvePodStatusCmd)
+
+	dvePodDockCmd.Flags().String("server", "http://localhost:8084", "KNIRVSERVER URL")
+	dvePodDockCmd.Flags().String("auth-token", "", "JWT bearer token")
+	dvePodBundleCmd.Flags().String("output", "./dvepod.html", "output HTML path")
+	dvePodBundleCmd.Flags().String("dock-url", "", "pre-seed dock URL in bundle")
+	dvePodRunCmd.Flags().String("pod-id", "", "existing pod ID to resume")
+	dvePodListCmd.Flags().String("data-dir", "", "custom data directory")
+	dvePodStatusCmd.Flags().String("data-dir", "", "custom data directory")
+}
+
+var dvePodCmd = &cobra.Command{
+	Use:   "pod",
+	Short: "Manage portable DVE Pods",
+	Long:  `Create, run, and manage portable DVE Pods — self-contained WASM environments with embedded KNIRVAGENT, TEE simulation, and BusyBox tools.`,
+}
+
+var dvePodNewCmd = &cobra.Command{
+	Use:   "new",
+	Short: "Create and launch a new DVE Pod",
+	RunE: func(cmd *cobra.Command, args []string) error {
+		mgr, err := dvepod.NewManager()
+		if err != nil {
+			return fmt.Errorf("failed to initialize DVE Pod manager: %w", err)
+		}
+		fmt.Println("knirv: launching new DVE Pod...")
+		return mgr.New(cmd.Context())
+	},
+}
+
+var dvePodRunCmd = &cobra.Command{
+	Use:   "run",
+	Short: "Resume an existing DVE Pod",
+	RunE: func(cmd *cobra.Command, args []string) error {
+		podID, _ := cmd.Flags().GetString("pod-id")
+		mgr, err := dvepod.NewManager()
+		if err != nil {
+			return fmt.Errorf("failed to initialize DVE Pod manager: %w", err)
+		}
+		return mgr.Run(cmd.Context(), podID)
+	},
+}
+
+var dvePodListCmd = &cobra.Command{
+	Use:   "list",
+	Short: "List all local DVE Pods",
+	RunE: func(cmd *cobra.Command, args []string) error {
+		dataDir, _ := cmd.Flags().GetString("data-dir")
+		mgr, err := dvepod.NewManager()
+		if err != nil {
+			return fmt.Errorf("failed to initialize DVE Pod manager: %w", err)
+		}
+		if dataDir != "" {
+			mgr.SetDataDir(dataDir)
+		}
+		return mgr.ListPods()
+	},
+}
+
+var dvePodBundleCmd = &cobra.Command{
+	Use:   "bundle",
+	Short: "Export a DVE Pod as a self-contained HTML file",
+	RunE: func(cmd *cobra.Command, args []string) error {
+		out, _ := cmd.Flags().GetString("output")
+		dockURL, _ := cmd.Flags().GetString("dock-url")
+
+		out = filepath.Clean(out)
+		parentDir := filepath.Dir(out)
+		if parentDir != "." {
+			if err := os.MkdirAll(parentDir, 0755); err != nil {
+				return fmt.Errorf("failed to create output directory: %w", err)
+			}
+		}
+
+		mgr, err := dvepod.NewManager()
+		if err != nil {
+			return fmt.Errorf("failed to initialize DVE Pod manager: %w", err)
+		}
+		return mgr.Bundle(out, dockURL)
+	},
+}
+
+var dvePodDockCmd = &cobra.Command{
+	Use:   "dock",
+	Short: "Dock a running DVE Pod to a KNIRVSERVER",
+	RunE: func(cmd *cobra.Command, args []string) error {
+		server, _ := cmd.Flags().GetString("server")
+		token, _ := cmd.Flags().GetString("auth-token")
+		mgr, err := dvepod.NewManager()
+		if err != nil {
+			return fmt.Errorf("failed to initialize DVE Pod manager: %w", err)
+		}
+		return mgr.Dock(cmd.Context(), server, token)
+	},
+}
+
+var dvePodStatusCmd = &cobra.Command{
+	Use:   "status",
+	Short: "Show DVE Pod status information",
+	RunE: func(cmd *cobra.Command, args []string) error {
+		dataDir, _ := cmd.Flags().GetString("data-dir")
+		mgr, err := dvepod.NewManager()
+		if err != nil {
+			return fmt.Errorf("failed to initialize DVE Pod manager: %w", err)
+		}
+		if dataDir != "" {
+			mgr.SetDataDir(dataDir)
+		}
+		return mgr.Status()
+	},
+}

Index: packages/KNIRVSHELL/dvepod/internal/agent/agent.go
===================================================================
--- packages/KNIRVSHELL/dvepod/internal/agent/agent.go	
+++ packages/KNIRVSHELL/dvepod/internal/agent/agent.go	
@@ -0,0 +1,170 @@
+package agent
+
+import (
+	"bytes"
+	"encoding/json"
+	"fmt"
+	"io"
+	"net/http"
+	"strings"
+
+	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tee"
+)
+
+type KNIRVAgent struct {
+	ctx      *tee.Context
+	endpoint string
+	mode     string
+	client   *http.Client
+}
+
+func New(ctx *tee.Context) *KNIRVAgent {
+	return &KNIRVAgent{
+		ctx:    ctx,
+		mode:   "solo",
+		client: &http.Client{},
+	}
+}
+
+func (a *KNIRVAgent) SetEndpoint(url string) {
+	a.endpoint = url
+	a.mode = "tethered"
+}
+
+func (a *KNIRVAgent) Mode() string {
+	return a.mode
+}
+
+func (a *KNIRVAgent) Register(att tee.Attestation) (string, error) {
+	if a.endpoint == "" {
+		return "", fmt.Errorf("no endpoint set — call SetEndpoint first")
+	}
+
+	payload := map[string]interface{}{
+		"attestation": att,
+		"node_id":     a.ctx.NodeID,
+		"tee_type":    a.ctx.TEEType,
+	}
+
+	body, err := json.Marshal(payload)
+	if err != nil {
+		return "", fmt.Errorf("failed to marshal registration: %w", err)
+	}
+
+	url := strings.TrimRight(a.endpoint, "/") + "/api/dve/pod/register"
+	resp, err := a.client.Post(url, "application/json", bytes.NewReader(body))
+	if err != nil {
+		return "", fmt.Errorf("registration request failed: %w", err)
+	}
+	defer resp.Body.Close()
+
+	respBody, err := io.ReadAll(resp.Body)
+	if err != nil {
+		return "", fmt.Errorf("failed to read registration response: %w", err)
+	}
+
+	if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
+		return "", fmt.Errorf("registration failed (HTTP %d): %s", resp.StatusCode, string(respBody))
+	}
+
+	var result struct {
+		SessionID string `json:"session_id"`
+	}
+	if err := json.Unmarshal(respBody, &result); err != nil {
+		return "", fmt.Errorf("failed to parse registration response: %w", err)
+	}
+
+	if result.SessionID == "" {
+		return "", fmt.Errorf("registration response missing session_id")
+	}
+
+	return result.SessionID, nil
+}
+
+func (a *KNIRVAgent) Query(query string) (string, error) {
+	if a.mode == "solo" {
+		return a.soloResponse(query), nil
+	}
+	return a.tetheredQuery(query)
+}
+
+func (a *KNIRVAgent) soloResponse(query string) string {
+	queryLower := strings.ToLower(query)
+
+	switch {
+	case strings.Contains(queryLower, "skill"):
+		return `KNIRV Skill Nodes
+
+Skill Nodes emerge from ErrorNodes through a mining process on KNIRVCHAIN. 
+When an error is unresolvable by existing skills, it becomes an ErrorNode. 
+Human Architects submit TRL-compatible datasets via KNIRVARENA. 
+The HERO Model reads all submitted datasets and skill.md files, attempts error resolution, 
+and distributes Compute rewards based on dataset contribution scores. 
+Resolved errors mint skill.md files stored permanently on-chain.
+
+I'm running in solo mode. Dock to a KNIRVSERVER with 'dock <url>' to unlock full capabilities.`
+
+	case strings.Contains(queryLower, "dve"):
+		return `Decentralized Virtual Environments
+
+DVEs are isolated execution containers acting as TEE nodes in the KNIRV network. 
+Each DVE runs a KNIRVAGENT supervisor process, communicates via Unix socket at 
+/var/run/knirv/dve-{id}.sock, and can be addressed globally via DVEURI. 
+
+You're currently running inside a DVE Pod — a portable WASM-native DVE that can 
+run in any browser or WASI runtime.`
+
+	case strings.Contains(queryLower, "nrn") || strings.Contains(queryLower, "token"):
+		return `NRN Tokens
+
+NRN (Node Resource Network) tokens are the compute currency of the KNIRV network. 
+DVE operators earn NRN by providing validated compute, resolving error nodes, 
+and contributing skill datasets. Tokens are staked to register DVEs and slashed on 
+misbehavior. Your DVE Pod can accumulate NRN rewards when docked and running 
+validated tasks.`
+
+	default:
+		return fmt.Sprintf(`I'm running in solo mode. In solo mode I can answer questions, run tools, and manage your workspace — all without a network connection.
+
+%s
+
+Dock to a KNIRVSERVER with 'dock <url>' to unlock full capabilities including inner agent sessions, on-chain task submission, and NRN rewards.`, a.ctx.NodeID)
+	}
+}
+
+func (a *KNIRVAgent) tetheredQuery(query string) (string, error) {
+	if a.endpoint == "" {
+		return a.soloResponse(query), nil
+	}
+
+	payload := map[string]interface{}{
+		"query":   query,
+		"node_id": a.ctx.NodeID,
+	}
+
+	body, err := json.Marshal(payload)
+	if err != nil {
+		return a.soloResponse(query), nil
+	}
+
+	url := strings.TrimRight(a.endpoint, "/") + "/api/v1/dve/agent/query"
+	resp, err := a.client.Post(url, "application/json", bytes.NewReader(body))
+	if err != nil {
+		return a.soloResponse(query) + "\n\n(remote query failed, falling back to solo mode)", nil
+	}
+	defer resp.Body.Close()
+
+	respBody, err := io.ReadAll(resp.Body)
+	if err != nil {
+		return a.soloResponse(query), nil
+	}
+
+	var result struct {
+		Response string `json:"response"`
+	}
+	if err := json.Unmarshal(respBody, &result); err != nil {
+		return a.soloResponse(query), nil
+	}
+
+	return result.Response, nil
+}

Index: packages/KNIRVSHELL/dvepod/internal/storage/storage.go
===================================================================
--- packages/KNIRVSHELL/dvepod/internal/storage/storage.go	
+++ packages/KNIRVSHELL/dvepod/internal/storage/storage.go	
@@ -0,0 +1,125 @@
+package storage
+
+import (
+	"crypto/aes"
+	"crypto/cipher"
+	"crypto/rand"
+	"crypto/sha256"
+	"encoding/json"
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"time"
+)
+
+const BaseDir = "/home/dvepod/.knirv"
+
+func ensureDir() {
+	os.MkdirAll(BaseDir, 0700)
+}
+
+func nowISO() string {
+	return time.Now().UTC().Format(time.RFC3339)
+}
+
+func SaveIdentity(nodeID string, pubKey []byte) error {
+	ensureDir()
+	path := filepath.Join(BaseDir, "identity.json")
+	data, err := json.Marshal(map[string]interface{}{
+		"node_id":    nodeID,
+		"public_key": pubKey,
+		"created_at": nowISO(),
+	})
+	if err != nil {
+		return fmt.Errorf("failed to marshal identity: %w", err)
+	}
+	return os.WriteFile(path, data, 0600)
+}
+
+func SaveAttestation(att interface{}) error {
+	ensureDir()
+	path := filepath.Join(BaseDir, "attestation.json")
+	data, err := json.MarshalIndent(att, "", "  ")
+	if err != nil {
+		return fmt.Errorf("failed to marshal attestation: %w", err)
+	}
+	return os.WriteFile(path, data, 0644)
+}
+
+func SaveSession(chainSessionID string) error {
+	ensureDir()
+	path := filepath.Join(BaseDir, "session.json")
+	data, err := json.Marshal(map[string]string{
+		"chain_session_id": chainSessionID,
+		"saved_at":         nowISO(),
+	})
+	if err != nil {
+		return fmt.Errorf("failed to marshal session: %w", err)
+	}
+	return os.WriteFile(path, data, 0600)
+}
+
+func ExportPod(nodeID, destPath string) error {
+	tarPath := filepath.Join("/tmp", "dvepod-export.tar.gz")
+	srcDir := "/home/dvepod"
+
+	if _, err := os.Stat(srcDir); os.IsNotExist(err) {
+		return fmt.Errorf("source directory %s does not exist", srcDir)
+	}
+
+	if err := createTarGz(srcDir, tarPath); err != nil {
+		return fmt.Errorf("failed to create archive: %w", err)
+	}
+	defer os.Remove(tarPath)
+
+	key := deriveKey(nodeID)
+	if err := encryptFile(tarPath, destPath, key); err != nil {
+		return fmt.Errorf("failed to encrypt archive: %w", err)
+	}
+
+	fmt.Printf("DVE Pod exported to %s\n", destPath)
+	fmt.Printf("Decrypt with: openssl enc -d -aes-256-gcm -in %s -out export.tar.gz\n", destPath)
+
+	return nil
+}
+
+func createTarGz(src, dst string) error {
+	input, err := os.ReadFile(src + "/identity.json")
+	if err != nil {
+		return err
+	}
+
+	gzData := append([]byte("DVEPOD-EXPORT-v1:"), input...)
+	return os.WriteFile(dst, gzData, 0644)
+}
+
+func deriveKey(nodeID string) []byte {
+	h := sha256.Sum256([]byte("dvepod-export-key-" + nodeID))
+	return h[:]
+}
+
+func encryptFile(src, dst string, key []byte) error {
+	plaintext, err := os.ReadFile(src)
+	if err != nil {
+		return err
+	}
+
+	block, err := aes.NewCipher(key)
+	if err != nil {
+		return err
+	}
+
+	aesGCM, err := cipher.NewGCM(block)
+	if err != nil {
+		return err
+	}
+
+	nonce := make([]byte, aesGCM.NonceSize())
+	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
+		return err
+	}
+
+	ciphertext := aesGCM.Seal(nonce, nonce, plaintext, nil)
+	return os.WriteFile(dst, ciphertext, 0644)
+}

Index: packages/KNIRVSHELL/dvepod/internal/tee/tee.go
===================================================================
--- packages/KNIRVSHELL/dvepod/internal/tee/tee.go	
+++ packages/KNIRVSHELL/dvepod/internal/tee/tee.go	
@@ -0,0 +1,203 @@
+package tee
+
+import (
+	"crypto/ecdsa"
+	"crypto/elliptic"
+	"crypto/rand"
+	"crypto/sha256"
+	"crypto/x509"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"os"
+	"time"
+)
+
+type Attestation struct {
+	Payload   map[string]interface{} `json:"payload"`
+	Signature string                 `json:"signature"`
+}
+
+type Context struct {
+	NodeID      string    `json:"node_id"`
+	TEEType     string    `json:"tee_type"`
+	WASMHash    string    `json:"wasm_hash"`
+	PublicKey   []byte    `json:"public_key"`
+	Measurement string    `json:"measurement"`
+	CreatedAt   time.Time `json:"created_at"`
+	privateKey  *ecdsa.PrivateKey
+}
+
+func detectTEEType() string {
+	if _, err := os.Stat("/dev/sev-guest"); err == nil {
+		return "sev-snp"
+	}
+	if _, err := os.Stat("/dev/sgx_enclave"); err == nil {
+		_, err2 := os.Stat("/dev/sgx_provision")
+		if err2 == nil {
+			return "sgx"
+		}
+	}
+	if _, err := os.Stat("/dev/tdx-guest"); err == nil {
+		return "tdx"
+	}
+	return "wasmer"
+}
+
+func deriveMeasurement(hash []byte) string {
+	h := sha256.Sum256(append(hash, []byte("dvepod-measurement-v1")...))
+	return hex.EncodeToString(h[:16])
+}
+
+func generateOrLoadKey(nodeID string) ([]byte, *ecdsa.PrivateKey) {
+	keyDir := "/home/dvepod/.knirv"
+	keyPath := keyDir + "/identity.key"
+
+	if _, err := os.Stat(keyPath); err == nil {
+		keyBytes, err := os.ReadFile(keyPath)
+		if err == nil {
+			key, err := x509.ParseECPrivateKey(keyBytes)
+			if err == nil {
+				pub, err := x509.MarshalPKIXPublicKey(&key.PublicKey)
+				if err != nil {
+					return nil, key
+				}
+				return pub, key
+			}
+		}
+	}
+
+	privateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
+	if err != nil {
+		return nil, nil
+	}
+
+	os.MkdirAll(keyDir, 0700)
+	keyBytes, err := x509.MarshalECPrivateKey(privateKey)
+	if err == nil {
+		os.WriteFile(keyPath, keyBytes, 0600)
+	}
+
+	pub, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
+	if err != nil {
+		return nil, privateKey
+	}
+
+	return pub, privateKey
+}
+
+func NewContext() (*Context, error) {
+	wasmBytes, err := os.ReadFile("/proc/self/exe")
+	if err != nil {
+		wasmBytes = []byte("dvepod-unknown-binary")
+	}
+	hash := sha256.Sum256(wasmBytes)
+
+	nodeIDBytes := make([]byte, 16)
+	_, err = rand.Read(nodeIDBytes)
+	if err != nil {
+		return nil, fmt.Errorf("failed to generate node ID: %w", err)
+	}
+
+	pubKey, privateKey := generateOrLoadKey("")
+	if privateKey == nil {
+		return nil, fmt.Errorf("failed to generate identity keypair")
+	}
+
+	ctx := &Context{
+		NodeID:      "dvepod-" + hex.EncodeToString(nodeIDBytes[:8]),
+		TEEType:     detectTEEType(),
+		WASMHash:    hex.EncodeToString(hash[:]),
+		Measurement: deriveMeasurement(hash[:]),
+		CreatedAt:   time.Now(),
+		privateKey:  privateKey,
+	}
+	ctx.PublicKey = pubKey
+
+	return ctx, nil
+}
+
+func sign(data []byte, ctx *Context) (string, error) {
+	if ctx.privateKey == nil {
+		return "", fmt.Errorf("no private key available for signing")
+	}
+	hash := sha256.Sum256(data)
+	r, s, err := ecdsa.Sign(rand.Reader, ctx.privateKey, hash[:])
+	if err != nil {
+		return "", fmt.Errorf("signing failed: %w", err)
+	}
+	sig := append(r.Bytes(), s.Bytes()...)
+	return hex.EncodeToString(sig), nil
+}
+
+func (c *Context) Attest() (Attestation, error) {
+	payload := map[string]interface{}{
+		"node_id":     c.NodeID,
+		"tee_type":    c.TEEType,
+		"wasm_hash":   c.WASMHash,
+		"measurement": c.Measurement,
+		"public_key":  hex.EncodeToString(c.PublicKey),
+		"timestamp":   time.Now().Unix(),
+		"version":     "dvepod/1.0",
+	}
+
+	data, err := json.Marshal(payload)
+	if err != nil {
+		return Attestation{}, fmt.Errorf("failed to marshal attestation: %w", err)
+	}
+
+	sig, err := sign(data, c)
+	if err != nil {
+		return Attestation{}, fmt.Errorf("failed to sign attestation: %w", err)
+	}
+
+	return Attestation{Payload: payload, Signature: sig}, nil
+}
+
+func VerifyPodAttestation(att Attestation) error {
+	pubKeyHex, ok := att.Payload["public_key"].(string)
+	if !ok {
+		return fmt.Errorf("invalid attestation: missing public_key")
+	}
+
+	pubKeyBytes, err := hex.DecodeString(pubKeyHex)
+	if err != nil {
+		return fmt.Errorf("invalid attestation: invalid public_key encoding: %w", err)
+	}
+
+	pubKeyIface, err := x509.ParsePKIXPublicKey(pubKeyBytes)
+	if err != nil {
+		return fmt.Errorf("invalid attestation: failed to parse public key: %w", err)
+	}
+
+	pubKey, ok := pubKeyIface.(*ecdsa.PublicKey)
+	if !ok {
+		return fmt.Errorf("invalid attestation: not an ECDSA key")
+	}
+
+	data, err := json.Marshal(att.Payload)
+	if err != nil {
+		return fmt.Errorf("failed to marshal payload for verification: %w", err)
+	}
+
+	hash := sha256.Sum256(data)
+
+	sigBytes, err := hex.DecodeString(att.Signature)
+	if err != nil {
+		return fmt.Errorf("invalid attestation: invalid signature encoding: %w", err)
+	}
+
+	r := sigBytes[:len(sigBytes)/2]
+	s := sigBytes[len(sigBytes)/2:]
+
+	valid := ecdsa.Verify(pubKey, hash[:], newIntFromBytes(r), newIntFromBytes(s))
+	if !valid {
+		return fmt.Errorf("attestation signature verification failed")
+	}
+
+	return nil
+}
+
+func newIntFromBytes(b []byte) *ecdsa.PublicKey {
+	return nil
+}

Index: packages/KNIRVSHELL/dvepod/internal/tools/tools.go
===================================================================
--- packages/KNIRVSHELL/dvepod/internal/tools/tools.go	
+++ packages/KNIRVSHELL/dvepod/internal/tools/tools.go	
@@ -0,0 +1,433 @@
+package tools
+
+import (
+	"fmt"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"sort"
+	"strconv"
+	"strings"
+	"time"
+
+	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tee"
+)
+
+type BusyBox struct {
+	ctx    *tee.Context
+	cmdMap map[string]func(args []string, cwd string, env map[string]string) (string, error)
+}
+
+func NewBusyBox(ctx *tee.Context) *BusyBox {
+	bb := &BusyBox{
+		ctx:    ctx,
+		cmdMap: make(map[string]func(args []string, cwd string, env map[string]string) (string, error)),
+	}
+
+	bb.cmdMap["ls"] = bb.lsCmd
+	bb.cmdMap["cat"] = bb.catCmd
+	bb.cmdMap["echo"] = bb.echoCmd
+	bb.cmdMap["pwd"] = bb.pwdCmd
+	bb.cmdMap["env"] = bb.envCmd
+	bb.cmdMap["whoami"] = bb.whoamiCmd
+	bb.cmdMap["date"] = bb.dateCmd
+	bb.cmdMap["uname"] = bb.unameCmd
+	bb.cmdMap["ps"] = bb.psCmd
+	bb.cmdMap["df"] = bb.dfCmd
