+func (bb *BusyBox) lsCmd(args []string, cwd string, env map[string]string) (string, error) {
+	long := false
+	var target string
+
+	for _, a := range args {
+		if a == "-l" || a == "-la" || a == "-al" {
+			long = true
+		} else if !strings.HasPrefix(a, "-") {
+			target = a
+		}
+	}
+
+	if target == "" {
+		target = cwd
+	} else if !strings.HasPrefix(target, "/") {
+		target = cwd + "/" + target
+	}
+	target = filepath.Clean(target)
+
+	entries, err := os.ReadDir(target)
+	if err != nil {
+		return "", fmt.Errorf("ls: %s: %v", target, err)
+	}
+
+	sort.Slice(entries, func(i, j int) bool {
+		return entries[i].Name() < entries[j].Name()
+	})
+
+	var out strings.Builder
+	if long {
+		fmt.Fprintf(&out, "total %d\n", len(entries))
+		for _, e := range entries {
+			info, err := e.Info()
+			perm := "-rw-r--r--"
+			size := "-"
+			mtime := ""
+			if err == nil {
+				perm = info.Mode().String()
+				if info.IsDir() {
+					perm = "drwxr-xr-x"
+				}
+				size = fmt.Sprintf("%6d", info.Size())
+				mtime = info.ModTime().Format("Jan 02 15:04")
+			} else if e.IsDir() {
+				perm = "drwxr-xr-x"
+			}
+
+			name := e.Name()
+			if e.IsDir() {
+				name = name + "/"
+			}
+			fmt.Fprintf(&out, "%s  1 dvepod  %s  %s  %s\n", perm, size, mtime, name)
+		}
+	} else {
+		var names []string
+		for _, e := range entries {
+			name := e.Name()
+			if e.IsDir() {
+				name = name + "/"
+			}
+			names = append(names, name)
+		}
+		out.WriteString(strings.Join(names, "  "))
+		out.WriteString("\n")
+	}
+
+	return out.String(), nil
+}
