package main

import (
	"bufio"
	"fmt"
	"os"

	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/agent"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/shell"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tee"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tools"
)

func main() {
	ctx, err := tee.NewContext()
	if err != nil {
		fmt.Fprintf(os.Stderr, "dvepod: failed to initialize TEE context: %v\n", err)
		os.Exit(1)
	}

	bb := tools.NewBusyBox(ctx)
	ag := agent.New(ctx)
	sh := shell.New(ctx, bb, ag)

	err = sh.Boot()
	if err != nil {
		fmt.Fprintf(os.Stderr, "dvepod: boot failed: %v\n", err)
		os.Exit(1)
	}

	scanner := bufio.NewScanner(os.Stdin)
	for {
		fmt.Fprint(os.Stdout, sh.Prompt())
		if !scanner.Scan() {
			break
		}
		sh.Exec(scanner.Text())
	}

	if scanErr := scanner.Err(); scanErr != nil {
		fmt.Fprintf(os.Stderr, "dvepod: read error: %v\n", scanErr)
		os.Exit(1)
	}
}

package tee

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"time"
)

type Attestation struct {
	Payload   map[string]interface{} `json:"payload"`
	Signature string                 `json:"signature"`
}

type Context struct {
	NodeID      string    `json:"node_id"`
	TEEType     string    `json:"tee_type"`
	WASMHash    string    `json:"wasm_hash"`
	PublicKey   []byte    `json:"public_key"`
	Measurement string    `json:"measurement"`
	CreatedAt   time.Time `json:"created_at"`
	privateKey  *ecdsa.PrivateKey
}

func detectTEEType() string {
	if _, err := os.Stat("/dev/sev-guest"); err == nil {
		return "sev-snp"
	}
	if _, err := os.Stat("/dev/sgx_enclave"); err == nil {
		_, err2 := os.Stat("/dev/sgx_provision")
		if err2 == nil {
			return "sgx"
		}
	}
	if _, err := os.Stat("/dev/tdx-guest"); err == nil {
		return "tdx"
	}
	return "wasmer"
}

func deriveMeasurement(hash []byte) string {
	h := sha256.Sum256(append(hash, []byte("dvepod-measurement-v1")...))
	return hex.EncodeToString(h[:16])
}

func generateOrLoadKey(nodeID string) ([]byte, *ecdsa.PrivateKey) {
	keyDir := "/home/dvepod/.knirv"
	keyPath := keyDir + "/identity.key"

	if _, err := os.Stat(keyPath); err == nil {
		keyBytes, err := os.ReadFile(keyPath)
		if err == nil {
			key, err := x509.ParseECPrivateKey(keyBytes)
			if err == nil {
				pub, err := x509.MarshalPKIXPublicKey(&key.PublicKey)
				if err != nil {
					return nil, key
				}
				return pub, key
			}
		}
	}

	privateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil
	}

	os.MkdirAll(keyDir, 0700)
	keyBytes, err := x509.MarshalECPrivateKey(privateKey)
	if err == nil {
		os.WriteFile(keyPath, keyBytes, 0600)
	}

	pub, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
	if err != nil {
		return nil, privateKey
	}

	return pub, privateKey
}

func NewContext() (*Context, error) {
	wasmBytes, err := os.ReadFile("/proc/self/exe")
	if err != nil {
		wasmBytes = []byte("dvepod-unknown-binary")
	}
	hash := sha256.Sum256(wasmBytes)

	nodeIDBytes := make([]byte, 16)
	_, err = rand.Read(nodeIDBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to generate node ID: %w", err)
	}

	pubKey, privateKey := generateOrLoadKey("")
	if privateKey == nil {
		return nil, fmt.Errorf("failed to generate identity keypair")
	}

	ctx := &Context{
		NodeID:      "dvepod-" + hex.EncodeToString(nodeIDBytes[:8]),
		TEEType:     detectTEEType(),
		WASMHash:    hex.EncodeToString(hash[:]),
		Measurement: deriveMeasurement(hash[:]),
		CreatedAt:   time.Now(),
		privateKey:  privateKey,
	}
	ctx.PublicKey = pubKey

	return ctx, nil
}

func sign(data []byte, ctx *Context) (string, error) {
	if ctx.privateKey == nil {
		return "", fmt.Errorf("no private key available for signing")
	}
	hash := sha256.Sum256(data)
	r, s, err := ecdsa.Sign(rand.Reader, ctx.privateKey, hash[:])
	if err != nil {
		return "", fmt.Errorf("signing failed: %w", err)
	}
	sig := append(r.Bytes(), s.Bytes()...)
	return hex.EncodeToString(sig), nil
}

func (c *Context) Attest() (Attestation, error) {
	payload := map[string]interface{}{
		"node_id":     c.NodeID,
		"tee_type":    c.TEEType,
		"wasm_hash":   c.WASMHash,
		"measurement": c.Measurement,
		"public_key":  hex.EncodeToString(c.PublicKey),
		"timestamp":   time.Now().Unix(),
		"version":     "dvepod/1.0",
	}

	data, err := json.Marshal(payload)
	if err != nil {
		return Attestation{}, fmt.Errorf("failed to marshal attestation: %w", err)
	}

	sig, err := sign(data, c)
	if err != nil {
		return Attestation{}, fmt.Errorf("failed to sign attestation: %w", err)
	}

	return Attestation{Payload: payload, Signature: sig}, nil
}

func VerifyPodAttestation(att Attestation) error {
	pubKeyHex, ok := att.Payload["public_key"].(string)
	if !ok {
		return fmt.Errorf("invalid attestation: missing public_key")
	}

	pubKeyBytes, err := hex.DecodeString(pubKeyHex)
	if err != nil {
		return fmt.Errorf("invalid attestation: invalid public_key encoding: %w", err)
	}

	pubKeyIface, err := x509.ParsePKIXPublicKey(pubKeyBytes)
	if err != nil {
		return fmt.Errorf("invalid attestation: failed to parse public key: %w", err)
	}

	pubKey, ok := pubKeyIface.(*ecdsa.PublicKey)
	if !ok {
		return fmt.Errorf("invalid attestation: not an ECDSA key")
	}

	data, err := json.Marshal(att.Payload)
	if err != nil {
		return fmt.Errorf("failed to marshal payload for verification: %w", err)
	}

	hash := sha256.Sum256(data)

	sigBytes, err := hex.DecodeString(att.Signature)
	if err != nil {
		return fmt.Errorf("invalid attestation: invalid signature encoding: %w", err)
	}

	r := sigBytes[:len(sigBytes)/2]
	s := sigBytes[len(sigBytes)/2:]

	valid := ecdsa.Verify(pubKey, hash[:], newIntFromBytes(r), newIntFromBytes(s))
	if !valid {
		return fmt.Errorf("attestation signature verification failed")
	}

	return nil
}

func newIntFromBytes(b []byte) *ecdsa.PublicKey {
	return nil
}

package shell

import (
	"fmt"
	"os"
	"strings"

	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/agent"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tee"
	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tools"
)

type Shell struct {
	ctx     *tee.Context
	bb      *tools.BusyBox
	agent   *agent.KNIRVAgent
	cwd     string
	history []string
	env     map[string]string
	mode    string
	dockURL string
}

func New(ctx *tee.Context, bb *tools.BusyBox, ag *agent.KNIRVAgent) *Shell {
	return &Shell{
		ctx:   ctx,
		bb:    bb,
		agent: ag,
		cwd:   "/home/dvepod",
		env: map[string]string{
			"HOME":         "/home/dvepod",
			"PATH":         "/usr/bin:/bin",
			"TERM":         "xterm-256color",
			"USER":         "dvepod",
			"DVE_ID":       ctx.NodeID,
			"DVE_MODE":     "solo",
			"TEE_TYPE":     ctx.TEEType,
			"KNIRV_VERSION": "1.0.0-pod",
		},
		mode:    "solo",
		history: make([]string, 0, 100),
	}
}

func (s *Shell) Boot() error {
	fmt.Fprintln(os.Stdout, "\033[36m╔══════════════════════════════════════════════╗\033[0m")
	fmt.Fprintln(os.Stdout, "\033[36m║\033[0m   \033[1m\033[97mKNIRV DVE Pod\033[0m \033[90mv1.0.0-pod\033[0m                  \033[36m║\033[0m")
	fmt.Fprintln(os.Stdout, "\033[36m║\033[0m   Portable Decentralized Virtual Environment  \033[36m║\033[0m")
	fmt.Fprintln(os.Stdout, "\033[36m╚══════════════════════════════════════════════╝\033[0m")
	fmt.Fprintln(os.Stdout)
	fmt.Fprintf(os.Stdout, "\033[33mDVE ID:\033[0m    %s\n", s.ctx.NodeID)
	fmt.Fprintf(os.Stdout, "\033[33mTEE Type:\033[0m  %s \033[90m(simulated enclave)\033[0m\n", s.ctx.TEEType)
	fmt.Fprintf(os.Stdout, "\033[33mMode:\033[0m      \033[92mSolo\033[0m \033[90m(offline-capable)\033[0m\n")
	fmt.Fprintf(os.Stdout, "\033[33mStorage:\033[0m   WASI FS\n")
	fmt.Fprintf(os.Stdout, "\033[33mWASM Hash:\033[0m %s\n", s.ctx.WASMHash[:16])
	fmt.Fprintln(os.Stdout)
	fmt.Fprintf(os.Stdout, "\033[90mType \033[0mhelp\033[90m for available commands.\033[0m\n")
	fmt.Fprintln(os.Stdout)
	return nil
}

func (s *Shell) Prompt() string {
	short := strings.Replace(s.cwd, s.env["HOME"], "~", 1)
	return fmt.Sprintf("dvepod@%s:%s$ ", s.mode, short)
}

func (s *Shell) print(out string, err error) {
	if err != nil {
		fmt.Fprintf(os.Stderr, "\033[31m%v\033[0m\n", err)
	}
	if out != "" {
		fmt.Fprint(os.Stdout, out)
	}
}

func (s *Shell) Exec(line string) {
	line = strings.TrimSpace(line)
	if line == "" {
		return
	}
	s.history = append(s.history, line)

	parts := ParseLine(line)
	if len(parts) == 0 {
		return
	}
	cmd, args := parts[0], parts[1:]

	switch cmd {
	case "ls", "cat", "echo", "mkdir", "rm", "cp", "mv",
		"env", "pwd", "ps", "curl", "grep", "wc", "find",
		"chmod", "whoami", "date", "df", "free", "uname":
		out, err := s.bb.Run(cmd, args, s.cwd, s.env)
		s.print(out, err)

	case "tee":
		s.cmdTEE(args)
	case "agent":
		s.cmdAgent(args)
	case "dock":
		s.cmdDock(args)
	case "undock":
		s.cmdUndock()
	case "net":
		s.cmdNet(args)
	case "nrn":
		s.cmdNRN(args)
	case "export":
		s.cmdExport(args)
	case "help":
		s.cmdHelp()
	case "clear":
		fmt.Print("\033[2J\033[H")
	case "history":
		s.cmdHistory()
	case "cd":
		s.cmdCD(args)
	case "storage":
		s.cmdStorage(args)
	case "version":
		s.cmdVersion()
	case "write":
		s.cmdWrite(args)
	default:
		fmt.Fprintf(os.Stderr, "dvepod: %s: command not found\n", cmd)
	}
}

func (s *Shell) cmdTEE(args []string) {
	sub := "status"
	if len(args) > 0 {
		sub = args[0]
	}

	switch sub {
	case "status":
		trustLevel := "L0 (solo)"
		if s.mode == "bridged" {
			trustLevel = "L2"
		} else if s.mode == "tethered" {
			trustLevel = "L1"
		}
		fmt.Fprintf(os.Stdout, "\033[1m\033[96mTEE Context\033[0m\n")
		fmt.Fprintf(os.Stdout, "  Type:        %s \033[90m(simulated enclave)\033[0m\n", s.ctx.TEEType)
		fmt.Fprintf(os.Stdout, "  Node ID:     %s\n", s.ctx.NodeID)
		fmt.Fprintf(os.Stdout, "  WASM Hash:   %s\n", s.ctx.WASMHash)
		fmt.Fprintf(os.Stdout, "  Trust Level: %s\n", trustLevel)
		fmt.Fprintf(os.Stdout, "  Keypair:     P-256 ECDSA \033[92m✓ generated\033[0m\n")
		fmt.Fprintf(os.Stdout, "  Attestation: \033[92m✓ self-signed\033[0m\n")

	case "attest":
		fmt.Fprintf(os.Stdout, "\033[90mGenerating attestation report...\033[0m\n")
		att, err := s.ctx.Attest()
		if err != nil {
			fmt.Fprintf(os.Stderr, "\033[31m✗ attestation failed: %v\033[0m\n", err)
			return
		}
		fmt.Fprintf(os.Stdout, "\033[92m✓ Attestation generated\033[0m\n")
		fmt.Fprintf(os.Stdout, "  Node ID:     %s\n", att.Payload["node_id"])
		fmt.Fprintf(os.Stdout, "  TEE Type:    %s\n", att.Payload["tee_type"])
		fmt.Fprintf(os.Stdout, "  WASM Hash:   %s\n", att.Payload["wasm_hash"])
		fmt.Fprintf(os.Stdout, "  Signature:   %s...\n", att.Signature[:16])

	case "verify":
		fmt.Fprintf(os.Stdout, "\033[33m⚠ Verification requires docking to KNIRVSERVER (L1+)\033[0m\n")
		fmt.Fprintf(os.Stdout, "  Use: dock <knirvserver-url>\n")

	default:
		fmt.Fprintf(os.Stderr, "tee: unknown subcommand '%s'. Try: status, attest, verify\n", sub)
	}
}

func (s *Shell) cmdAgent(args []string) {
	query := strings.Join(args, " ")
	query = strings.Trim(query, "\"'")
	if query == "" {
		fmt.Fprintf(os.Stderr, "\033[31magent: usage: agent \"<query>\"\033[0m\n")
		return
	}

	fmt.Fprintf(os.Stdout, "\033[90m[KNIRVAGENT] %s › %s\033[0m\n", s.mode, query)
	result, err := s.agent.Query(query)
	if err != nil {
		fmt.Fprintf(os.Stderr, "\033[31m✗ agent error: %v\033[0m\n", err)
		return
	}
	fmt.Fprintln(os.Stdout, result)
}

func (s *Shell) cmdDock(args []string) {
	if len(args) == 0 {
		fmt.Fprintln(os.Stdout, "usage: dock <knirvserver-url> [--node-id <id>]")
		return
	}

	serverURL := args[0]
	s.dockURL = serverURL
	s.agent.SetEndpoint(serverURL)
	s.mode = "tethered"

	att, err := s.ctx.Attest()
	if err != nil {
		fmt.Fprintf(os.Stderr, "\033[31m✗ attestation failed: %v\033[0m\n", err)
		s.mode = "solo"
		s.dockURL = ""
		return
	}

	sid, err := s.agent.Register(att)
	if err != nil {
		fmt.Fprintf(os.Stderr, "\033[31m✗ dock failed: %v\033[0m\n", err)
		s.mode = "solo"
		s.dockURL = ""
		return
	}

	s.env["CHAIN_SESSION_ID"] = sid
	s.mode = "bridged"
	fmt.Fprintf(os.Stdout, "\033[32m✓ docked to %s (session: %s)\033[0m\n", serverURL, sid[:12])
}

func (s *Shell) cmdUndock() {
	if s.mode == "solo" {
		fmt.Fprintf(os.Stdout, "\033[33mNot currently docked.\033[0m\n")
		return
	}
	s.mode = "solo"
	s.dockURL = ""
	delete(s.env, "CHAIN_SESSION_ID")
	fmt.Fprintf(os.Stdout, "\033[33mDisconnected. Running in solo mode.\033[0m\n")
}

