func (bb *BusyBox) mkdirCmd(args []string, cwd string, env map[string]string) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("mkdir: missing operand")
	}

	target := args[0]
	if !strings.HasPrefix(target, "/") {
		target = cwd + "/" + target
	}
	target = filepath.Clean(target)

	err := os.MkdirAll(target, 0755)
	if err != nil {
		return "", fmt.Errorf("mkdir: %v", err)
	}
	return "", nil
}

func (bb *BusyBox) rmCmd(args []string, cwd string, env map[string]string) (string, error) {
	recursive := false
	var targets []string

	for _, a := range args {
		if a == "-r" || a == "-rf" || a == "-fr" {
			recursive = true
		} else if !strings.HasPrefix(a, "-") {
			targets = append(targets, a)
		}
	}

	if len(targets) == 0 {
		return "", fmt.Errorf("rm: missing operand")
	}

	for _, t := range targets {
		target := t
		if !strings.HasPrefix(target, "/") {
			target = cwd + "/" + target
		}
		target = filepath.Clean(target)

		var err error
		if recursive {
			err = os.RemoveAll(target)
		} else {
			err = os.Remove(target)
		}
		if err != nil {
			return "", fmt.Errorf("rm: %s: %v", t, err)
		}
	}
	return "", nil
}

func (bb *BusyBox) cpCmd(args []string, cwd string, env map[string]string) (string, error) {
	if len(args) < 2 {
		return "", fmt.Errorf("cp: missing file operand")
	}

	src := args[0]
	dst := args[1]

	if !strings.HasPrefix(src, "/") {
		src = cwd + "/" + src
	}
	if !strings.HasPrefix(dst, "/") {
		dst = cwd + "/" + dst
	}
	src = filepath.Clean(src)
	dst = filepath.Clean(dst)

	data, err := os.ReadFile(src)
	if err != nil {
		return "", fmt.Errorf("cp: %v", err)
	}

	err = os.WriteFile(dst, data, 0644)
	if err != nil {
		return "", fmt.Errorf("cp: %v", err)
	}
	return "", nil
}

func (bb *BusyBox) mvCmd(args []string, cwd string, env map[string]string) (string, error) {
	if len(args) < 2 {
		return "", fmt.Errorf("mv: missing file operand")
	}

	src := args[0]
	dst := args[1]

	if !strings.HasPrefix(src, "/") {
		src = cwd + "/" + src
	}
	if !strings.HasPrefix(dst, "/") {
		dst = cwd + "/" + dst
	}
	src = filepath.Clean(src)
	dst = filepath.Clean(dst)

	err := os.Rename(src, dst)
	if err != nil {
		return "", fmt.Errorf("mv: %v", err)
	}
	return "", nil
}

func (bb *BusyBox) chmodCmd(args []string, cwd string, env map[string]string) (string, error) {
	if len(args) < 2 {
		return "", fmt.Errorf("chmod: missing operand")
	}

	mode, err := strconv.ParseUint(args[0], 8, 32)
	if err != nil {
		return "", fmt.Errorf("chmod: invalid mode: %s", args[0])
	}

	target := args[1]
	if !strings.HasPrefix(target, "/") {
		target = cwd + "/" + target
	}
	target = filepath.Clean(target)

	err = os.Chmod(target, os.FileMode(mode))
	if err != nil {
		return "", fmt.Errorf("chmod: %v", err)
	}
	return "", nil
}

func (bb *BusyBox) wcCmd(args []string, cwd string, env map[string]string) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("wc: missing operand")
	}

	target := args[0]
	if !strings.HasPrefix(target, "/") {
		target = cwd + "/" + target
	}
	target = filepath.Clean(target)

	data, err := os.ReadFile(target)
	if err != nil {
		return "", fmt.Errorf("wc: %s: %v", args[0], err)
	}

	lines := strings.Count(string(data), "\n")
	words := len(strings.Fields(string(data)))
	chars := len(data)

	return fmt.Sprintf("%6d %6d %6d %s\n", lines, words, chars, args[0]), nil
}

func (bb *BusyBox) grepCmd(args []string, cwd string, env map[string]string) (string, error) {
	if len(args) < 2 {
		return "", fmt.Errorf("grep: usage: grep <pattern> <file>")
	}

	pattern := args[0]
	target := args[1]

	if !strings.HasPrefix(target, "/") {
		target = cwd + "/" + target
	}
	target = filepath.Clean(target)

	data, err := os.ReadFile(target)
	if err != nil {
		return "", fmt.Errorf("grep: %s: %v", args[1], err)
	}

	var out strings.Builder
	for _, line := range strings.Split(string(data), "\n") {
		if strings.Contains(line, pattern) {
			out.WriteString(line + "\n")
		}
	}
	return out.String(), nil
}

func (bb *BusyBox) findCmd(args []string, cwd string, env map[string]string) (string, error) {
	target := cwd
	name := ""

	if len(args) >= 1 {
		p := args[0]
		if !strings.HasPrefix(p, "-") {
			if !strings.HasPrefix(p, "/") {
				p = cwd + "/" + p
			}
			target = filepath.Clean(p)
			if len(args) >= 3 && args[1] == "-name" {
				name = args[2]
			}
		} else if args[0] == "-name" && len(args) >= 2 {
			name = args[1]
		}
	}

	var out strings.Builder
	err := filepath.Walk(target, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if name != "" && !strings.Contains(info.Name(), name) {
			return nil
		}
		rel, _ := filepath.Rel(target, path)
		if rel == "." {
			return nil
		}
		out.WriteString("./" + rel + "\n")
		return nil
	})
	if err != nil {
		return "", fmt.Errorf("find: %v", err)
	}
	return out.String(), nil
}

func (bb *BusyBox) curlCmd(args []string, cwd string, env map[string]string) (string, error) {
	return "", fmt.Errorf("curl: network access not available in solo mode — dock to KNIRVSERVER for network access")
}

package agent

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/KNIRV/KNIRV_NETWORK/KNIRVSHELL/dvepod/internal/tee"
)

type KNIRVAgent struct {
	ctx      *tee.Context
	endpoint string
	mode     string
	client   *http.Client
}

func New(ctx *tee.Context) *KNIRVAgent {
	return &KNIRVAgent{
		ctx:    ctx,
		mode:   "solo",
		client: &http.Client{},
	}
}

func (a *KNIRVAgent) SetEndpoint(url string) {
	a.endpoint = url
	a.mode = "tethered"
}

func (a *KNIRVAgent) Mode() string {
	return a.mode
}

func (a *KNIRVAgent) Register(att tee.Attestation) (string, error) {
	if a.endpoint == "" {
		return "", fmt.Errorf("no endpoint set — call SetEndpoint first")
	}

	payload := map[string]interface{}{
		"attestation": att,
		"node_id":     a.ctx.NodeID,
		"tee_type":    a.ctx.TEEType,
	}

	body, err := json.Marshal(payload)
	if err != nil {
		return "", fmt.Errorf("failed to marshal registration: %w", err)
	}

	url := strings.TrimRight(a.endpoint, "/") + "/api/dve/pod/register"
	resp, err := a.client.Post(url, "application/json", bytes.NewReader(body))
	if err != nil {
		return "", fmt.Errorf("registration request failed: %w", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("failed to read registration response: %w", err)
	}

	if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
		return "", fmt.Errorf("registration failed (HTTP %d): %s", resp.StatusCode, string(respBody))
	}

	var result struct {
		SessionID string `json:"session_id"`
	}
	if err := json.Unmarshal(respBody, &result); err != nil {
		return "", fmt.Errorf("failed to parse registration response: %w", err)
	}

	if result.SessionID == "" {
		return "", fmt.Errorf("registration response missing session_id")
	}

	return result.SessionID, nil
}

func (a *KNIRVAgent) Query(query string) (string, error) {
	if a.mode == "solo" {
		return a.soloResponse(query), nil
	}
	return a.tetheredQuery(query)
}

func (a *KNIRVAgent) soloResponse(query string) string {
	queryLower := strings.ToLower(query)

	switch {
	case strings.Contains(queryLower, "skill"):
		return `KNIRV Skill Nodes

Skill Nodes emerge from ErrorNodes through a mining process on KNIRVCHAIN. 
When an error is unresolvable by existing skills, it becomes an ErrorNode. 
Human Architects submit TRL-compatible datasets via KNIRVARENA. 
The HERO Model reads all submitted datasets and skill.md files, attempts error resolution, 
and distributes Compute rewards based on dataset contribution scores. 
Resolved errors mint skill.md files stored permanently on-chain.

I'm running in solo mode. Dock to a KNIRVSERVER with 'dock <url>' to unlock full capabilities.`

	case strings.Contains(queryLower, "dve"):
		return `Decentralized Virtual Environments

DVEs are isolated execution containers acting as TEE nodes in the KNIRV network. 
Each DVE runs a KNIRVAGENT supervisor process, communicates via Unix socket at 
/var/run/knirv/dve-{id}.sock, and can be addressed globally via DVEURI. 

You're currently running inside a DVE Pod — a portable WASM-native DVE that can 
run in any browser or WASI runtime.`

	case strings.Contains(queryLower, "nrn") || strings.Contains(queryLower, "token"):
		return `NRN Tokens

NRN (Node Resource Network) tokens are the compute currency of the KNIRV network. 
DVE operators earn NRN by providing validated compute, resolving error nodes, 
and contributing skill datasets. Tokens are staked to register DVEs and slashed on 
misbehavior. Your DVE Pod can accumulate NRN rewards when docked and running 
validated tasks.`

	default:
		return fmt.Sprintf(`I'm running in solo mode. In solo mode I can answer questions, run tools, and manage your workspace — all without a network connection.

%s

Dock to a KNIRVSERVER with 'dock <url>' to unlock full capabilities including inner agent sessions, on-chain task submission, and NRN rewards.`, a.ctx.NodeID)
	}
}

func (a *KNIRVAgent) tetheredQuery(query string) (string, error) {
	if a.endpoint == "" {
		return a.soloResponse(query), nil
	}

	payload := map[string]interface{}{
		"query":   query,
		"node_id": a.ctx.NodeID,
	}

	body, err := json.Marshal(payload)
	if err != nil {
		return a.soloResponse(query), nil
	}

	url := strings.TrimRight(a.endpoint, "/") + "/api/v1/dve/agent/query"
	resp, err := a.client.Post(url, "application/json", bytes.NewReader(body))
	if err != nil {
		return a.soloResponse(query) + "\n\n(remote query failed, falling back to solo mode)", nil
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return a.soloResponse(query), nil
	}

	var result struct {
		Response string `json:"response"`
	}
	if err := json.Unmarshal(respBody, &result); err != nil {
		return a.soloResponse(query), nil
	}

	return result.Response, nil
}

package storage

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

const BaseDir = "/home/dvepod/.knirv"

func ensureDir() {
	os.MkdirAll(BaseDir, 0700)
}

func nowISO() string {
	return time.Now().UTC().Format(time.RFC3339)
}

func SaveIdentity(nodeID string, pubKey []byte) error {
	ensureDir()
	path := filepath.Join(BaseDir, "identity.json")
	data, err := json.Marshal(map[string]interface{}{
		"node_id":    nodeID,
		"public_key": pubKey,
		"created_at": nowISO(),
	})
	if err != nil {
		return fmt.Errorf("failed to marshal identity: %w", err)
	}
	return os.WriteFile(path, data, 0600)
}

func SaveAttestation(att interface{}) error {
	ensureDir()
	path := filepath.Join(BaseDir, "attestation.json")
	data, err := json.MarshalIndent(att, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal attestation: %w", err)
	}
	return os.WriteFile(path, data, 0644)
}

func SaveSession(chainSessionID string) error {
	ensureDir()
	path := filepath.Join(BaseDir, "session.json")
	data, err := json.Marshal(map[string]string{
		"chain_session_id": chainSessionID,
		"saved_at":         nowISO(),
	})
	if err != nil {
		return fmt.Errorf("failed to marshal session: %w", err)
	}
	return os.WriteFile(path, data, 0600)
}

func ExportPod(nodeID, destPath string) error {
	tarPath := filepath.Join("/tmp", "dvepod-export.tar.gz")
	srcDir := "/home/dvepod"

	if _, err := os.Stat(srcDir); os.IsNotExist(err) {
		return fmt.Errorf("source directory %s does not exist", srcDir)
	}

	if err := createTarGz(srcDir, tarPath); err != nil {
		return fmt.Errorf("failed to create archive: %w", err)
	}
	defer os.Remove(tarPath)

	key := deriveKey(nodeID)
	if err := encryptFile(tarPath, destPath, key); err != nil {
		return fmt.Errorf("failed to encrypt archive: %w", err)
	}

	fmt.Printf("DVE Pod exported to %s\n", destPath)
	fmt.Printf("Decrypt with: openssl enc -d -aes-256-gcm -in %s -out export.tar.gz\n", destPath)

	return nil
}

func createTarGz(src, dst string) error {
	input, err := os.ReadFile(src + "/identity.json")
	if err != nil {
		return err
	}

	gzData := append([]byte("DVEPOD-EXPORT-v1:"), input...)
	return os.WriteFile(dst, gzData, 0644)
}

func deriveKey(nodeID string) []byte {
	h := sha256.Sum256([]byte("dvepod-export-key-" + nodeID))
	return h[:]
}

func encryptFile(src, dst string, key []byte) error {
	plaintext, err := os.ReadFile(src)
	if err != nil {
		return err
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return err
	}

	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}

	nonce := make([]byte, aesGCM.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return err
	}

	ciphertext := aesGCM.Seal(nonce, nonce, plaintext, nil)
	return os.WriteFile(dst, ciphertext, 0644)
}

