 	// Initialize embedded KNIRVCHAIN for blockchain and mining
 	var chainManager *knirvchain.Manager
 	log.Printf("DEBUG: cfg.Chain.Enabled = %v", cfg.Chain.Enabled)
 	if cfg.Chain.Enabled {
