 	target := args[0]
 	if !strings.HasPrefix(target, "/") {
 		target = cwd + "/" + target
 	}
 	target = filepath.Clean(target)

 	data, err := os.ReadFile(target)
 	if err != nil {
 		return "", fmt.Errorf("cat: %s: %v", args[0], err)
 	}
 	return string(data), nil
 }

